-- Add the current Apple lineup without changing existing products or homepage selections.
-- Names are checked too, so products already added through the admin are preserved.
begin;
insert into public.products
  (id, category, name, description, image, specs, views, finishes, price, published, is_demo, sort_order)
select x.id, x.category, x.name, x.description, x.image, x.specs, x.views, x.finishes, x.price, true, false, x.sort_order
from jsonb_to_recordset('[{"id":"iphone-18-pro-max","name":"iPhone 18 Pro Max","category":"telefona","price":1499,"image":"phone-18-pro-max-burgundy.webp","description":"iPhone 18 Pro Max me ekran 6,9 inç, çip A20 Pro dhe sistem kamerash Pro Fusion 48 MP.","specs":[["Marka","Apple"],["Ekrani","6,9 inç"],["Çipi","A20 Pro"],["Kamera","Pro Fusion 48 MP"]],"finishes":[["Burgundy","#754453","phone-18-pro-max-burgundy.webp"],["Glacier","#c4d3e1","phone-18-pro-max-glacier.webp"]],"views":[["Burgundy","phone-18-pro-max-burgundy.webp"],["Glacier","phone-18-pro-max-glacier.webp"]],"sort_order":10},{"id":"iphone-18-pro","name":"iPhone 18 Pro","category":"telefona","price":1299,"image":"phone-18-pro-glacier.webp","description":"iPhone 18 Pro me ekran 6,3 inç, çip A20 Pro dhe kamerë kryesore me aperturë të ndryshueshme.","specs":[["Marka","Apple"],["Ekrani","6,3 inç"],["Çipi","A20 Pro"],["Ngjyra në foto","Glacier"]],"sort_order":11},{"id":"iphone-duo","name":"iPhone Duo","category":"telefona","price":2199,"image":"phone-duo-white.webp","description":"iPhone me ekran të palosshëm 7,6 inç, çip A20 Pro dhe kornizë titani. Për punë dhe argëtim në një ekran më të madh.","specs":[["Marka","Apple"],["Ekrani i brendshëm","7,6 inç"],["Çipi","A20 Pro"],["Ngjyra në foto","Star White"]],"sort_order":12},{"id":"iphone-17e","name":"iPhone 17e","category":"telefona","price":599,"image":"phone-17e-white.webp","description":"iPhone 17e për komunikim, fotografi dhe përdorim të përditshëm. Pyet dyqanin për kapacitetet e disponueshme.","specs":[["Marka","Apple"],["Modeli","iPhone 17e"],["Ngjyra në foto","White"]],"sort_order":13},{"id":"ipad-air-m4-11","name":"iPad Air 11″ M4","category":"tableta","price":649,"image":"tablet-air-m4-11.webp","description":"iPad Air me çip M4 dhe ekran Liquid Retina 11 inç. Për shënime, mësim, punë dhe krijimtari.","specs":[["Marka","Apple"],["Ekrani","11 inç"],["Çipi","M4"],["Lidhja","Wi-Fi"]],"sort_order":14},{"id":"ipad-air-m4-13","name":"iPad Air 13″ M4","category":"tableta","price":849,"image":"tablet-air-m4-13.webp","description":"iPad Air me çip M4 dhe ekran Liquid Retina 13 inç. Për shënime, mësim, punë dhe krijimtari.","specs":[["Marka","Apple"],["Ekrani","13 inç"],["Çipi","M4"],["Lidhja","Wi-Fi"]],"sort_order":15},{"id":"ipad-pro-m5-11","name":"iPad Pro 11″ M5","category":"tableta","price":1099,"image":"tablet-pro-m5-11.webp","description":"iPad Pro me çip M5 dhe ekran Ultra Retina XDR 11 inç. Fuqi për aplikacione krijuese dhe punë të avancuar.","specs":[["Marka","Apple"],["Ekrani","11 inç"],["Çipi","M5"],["Lidhja","Wi-Fi"]],"sort_order":16},{"id":"ipad-pro-m5-13","name":"iPad Pro 13″ M5","category":"tableta","price":1399,"image":"tablet-pro-m5-13.webp","description":"iPad Pro me çip M5 dhe ekran Ultra Retina XDR 13 inç. Fuqi për aplikacione krijuese dhe punë të avancuar.","specs":[["Marka","Apple"],["Ekrani","13 inç"],["Çipi","M5"],["Lidhja","Wi-Fi"]],"sort_order":17},{"id":"ipad-mini-a20-pro","name":"iPad mini A20 Pro","category":"tableta","price":649,"image":"tablet-mini-a20pro.webp","description":"iPad mini me çip A20 Pro dhe ekran OLED 8,5 inç. Një tablet kompakt për lexim, shënime dhe argëtim.","specs":[["Marka","Apple"],["Ekrani","8,5 inç OLED"],["Çipi","A20 Pro"],["Ngjyra në foto","Midnight"]],"sort_order":18},{"id":"ipad-a16","name":"iPad 11″ A16","category":"tableta","price":379,"image":"tablet-a16-blue.webp","description":"iPad me ekran 11 inç dhe çip A16. Për mësim, video, shënime dhe përdorim të përditshëm.","specs":[["Marka","Apple"],["Ekrani","11 inç"],["Çipi","A16"],["Lidhja","Wi-Fi"]],"sort_order":19},{"id":"watch-series-12","name":"Apple Watch Series 12","category":"aksesore","price":449,"image":"watch-series-12.webp","description":"Apple Watch Series 12 me çip S11 dhe sensorë të rinj për shëndetin, aktivitetin dhe stërvitjen.","specs":[["Marka","Apple"],["Modeli","Series 12"],["Çipi","S11"]],"sort_order":20},{"id":"watch-ultra-4","name":"Apple Watch Ultra 4","category":"aksesore","price":899,"image":"watch-ultra-4.webp","description":"Apple Watch Ultra 4 me kasë titani, çip S11 dhe GPS të avancuar. Për sport dhe aktivitete në natyrë.","specs":[["Marka","Apple"],["Modeli","Ultra 4"],["Çipi","S11"],["Materiali","Titan"]],"sort_order":21},{"id":"airpods-5","name":"AirPods 5","category":"aksesore","price":179,"image":"audio-airpods-5.webp","description":"Kufje pa kabllo me anulim aktiv të zhurmës, Adaptive Audio dhe kuti karikimi USB-C.","specs":[["Marka","Apple"],["Lloji","Kufje pa kabllo"],["Anulimi i zhurmës","Aktiv"],["Karikimi","USB-C"]],"sort_order":22},{"id":"airpods-max-2","name":"AirPods Max 2","category":"aksesore","price":599,"image":"audio-airpods-max-2.webp","description":"Kufje me çip H2, anulim aktiv të zhurmës dhe Adaptive Audio. Lidhje USB-C për karikim dhe audio.","specs":[["Marka","Apple"],["Lloji","Kufje over-ear"],["Çipi","H2"],["Lidhja","USB-C"]],"sort_order":23}]'::jsonb)
as x(id text, category text, name text, description text, image text, specs jsonb, views jsonb, finishes jsonb, price numeric, sort_order integer)
where not exists (select 1 from public.products p where lower(trim(p.name)) = lower(trim(x.name)))
on conflict (id) do nothing;
commit;
